package mod.cdv.tnpc.social.client;
import mod.cdv.tnpc.tactical.SocialR;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;import java.util.*;
public final class ConversationScreen extends Screen {
 final String[] data;int page;static int lastPage;
 public ConversationScreen(String value){super(Component.translatable("soc.screen.title"));data=value.split("\n",-1);page=lastPage;}
 public static void open(String value){if(value.length()>8192||value.split("\n",-1).length!=12)return;Minecraft mc=Minecraft.getInstance();if(mc.player==null)return;if(mc.screen instanceof ConversationScreen old)lastPage=old.page;else lastPage=0;mc.setScreen(new ConversationScreen(value));}
 static Component tr(String key,Object...args){return Component.translatable(key,args);}void action(String key){Object player=Minecraft.getInstance().player;if(player==null)return;SocialR.call(SocialR.get(player,"connection"),"sendCommand","superviviente "+key);if(key.equals("inventory"))Minecraft.getInstance().setScreen(null);}
 void button(String action,int x,int y,int w){Button b=addRenderableWidget(Button.builder(tr("soc.button."+action),v->action(action)).bounds(x,y,w,20).build());if(Set.of("inventory","follow","stay","patrol","farm","scavenge","clean","craft","cook","deliver","depot","dismiss","free").contains(action))b.active=data[6].equals("ally");}
 protected void init(){int top=Math.max(4,(height-212)/2),left=width/2-145;String[][] pages={{"greet","weather","day","time","feeling","past","horde","rumor","promise","joke"},{"gift","heal","invite","inventory","depot","dismiss"},{"follow","stay","patrol","farm","scavenge","clean","craft","cook","deliver","free"}};String[] actions=pages[page];for(int i=0;i<actions.length;i++)button(actions[i],left+(i%2)*148,top+88+(i/2)*20,142);for(int i=0;i<3;i++){final int target=i;addRenderableWidget(Button.builder(tr("soc.tab."+i),b->{lastPage=target;Minecraft.getInstance().setScreen(new ConversationScreen(String.join("\n",data)));}).bounds(left+i*98,top+192,94,20).build());}}
 public void render(GuiGraphics g,int x,int y,float p){g.fill(0,0,width,height,0xc0101410);int top=Math.max(4,(height-212)/2),cx=width/2;g.drawCenteredString(font,Component.literal(data[1]),cx,top,0xffe6d3a3);g.drawCenteredString(font,tr("soc.summary",tr("soc.kind."+data[2]),tr("soc.persona."+data[3]),data[4],data[5]),cx,top+14,0xffbfcdb5);
  int lineY=top+31;Component speech=tr(data[9],data[10],data[11]);for(Object line:(Iterable<?>)SocialR.call(font,"split",speech,286)){SocialR.call(g,"drawCenteredString",font,line,cx,lineY,0xffeeeecc);lineY+=10;if(lineY>top+56)break;}Component personality=tr("dialog.soc.persona."+data[3]+"."+Math.floorMod(data[9].hashCode(),4));for(Object line:(Iterable<?>)SocialR.call(font,"split",personality,286)){SocialR.call(g,"drawCenteredString",font,line,cx,lineY,0xff9daf99);lineY+=10;if(lineY>top+72)break;}
  g.drawCenteredString(font,tr("soc.order",tr("soc.button."+data[7]),data[8]),cx,top+76,0xffabbf9c);super.render(g,x,y,p);
 }
 public boolean isPauseScreen(){return false;}public boolean shouldCloseOnEsc(){return true;}
}
